def solve(temps: list[int]) -> list[int]:
    answer = [0] * len(temps)
    stack = []
    for day, temp in enumerate(temps):
        while stack and temps[stack[-1]] < temp:
            waiting_day = stack.pop()
            answer[waiting_day] = day - waiting_day
        stack.append(day)
    return answer

